from abc import ABCMeta, abstractmethod, abstractproperty

from six import with_metaclass
from typing import ClassVar

from taf.cloud.cbam.schemas.problem_details import ProblemDetails
from taf.cloud.cbam.schemas.vnf_info import VnfInfo


class SupportedVnfSchemas(object):
    VnfInfo = VnfInfo  # type: ClassVar
    ProblemDetails = ProblemDetails  # type: ClassVar


class VNF(with_metaclass(ABCMeta, object)):
    @abstractproperty
    def supported_schemas(self):
        raise NotImplementedError

    @abstractmethod
    def create(self, vnf_info):
        raise NotImplementedError

    @abstractmethod
    def query_all_vnfs(self):
        raise NotImplementedError

    @abstractmethod
    def query_one(self, vnf_info):
        raise NotImplementedError

    @abstractmethod
    def get_vim_info(self, vnf_info, vim_info):
        raise NotImplementedError

    @abstractmethod
    def put_vim_info(self,
                     vnf_instance_name,
                     vim_id,
                     interface_info,
                     vim_info_type,
                     **kwargs):
        raise NotImplementedError

    def instantiate(self,
                    name,
                    path,
                    password,
                    flavour_id=None):
        raise NotImplementedError

    @abstractmethod
    def modify(self, name, path):
        raise NotImplementedError

    @abstractmethod
    def terminate(self,
                  name,
                  termination_type=None,
                  graceful_termination_timeout=None):
        raise NotImplementedError

    @abstractmethod
    def delete_vnf(self, name):
        raise NotImplementedError

    @abstractmethod
    def upgrade(self, name, vnfd_id):
        raise NotImplementedError

    @abstractmethod
    def get_operation_execution_info(self,
                                     operation_execution):
        raise NotImplementedError

    @abstractmethod
    def post_custom_operation(self,
                              vnf_instance_name,
                              custom_operation_name,
                              additional_params=None):
        raise NotImplementedError
